            group("existing alternate succeeds before any fresh lookup",()->{JSONObject old=variants("alternate",3,false);List<String> urls=urls(old);PlaybackSources.register(old,VID,false);NetworkGuard.outcomes.put(urls.get(0),"http403");File target=part("alternate");PlaybackSources.download(urls.get(0),target,64,QUALITY);check((attempts().equals(urls.subList(0,2))||attempts().equals(Arrays.asList(urls.get(0),urls.get(0),urls.get(1))))&&lookups.isEmpty(),"successful old alternate stops before unused variant or refresh");check(CencDecryptor.urls.equals(Collections.singletonList(urls.get(1))),"failed primary never decrypts");cleanStarts();assertHeaders(old);noProbe();finish(target);});
