                JSONObject old=variants("bound-old",8,false),fresh=variants("bound-new",8,true);List<String> expected=with403Retry(urls(old),0);expected.addAll(urls(fresh).subList(0,7));for(String url:urls(old))NetworkGuard.outcomes.put(url,"http403");for(String url:urls(fresh))NetworkGuard.outcomes.put(url,"http403");PlaybackSources.register(old,VID,false);reply(fresh);
